public static class NeonEnemyAssets {
 const string Root="Assets/Game/Resources/Detailed/NeonEnemies/",Out="D:/VideoGame/artifacts/biome-parallel/enemy-production/neon/";
 [Serializable] class Maps {public string Albedo,Normal,MetalSmooth,Occlusion,Emission;}
 [Serializable] class Surface {public string name,id;public Maps maps;public float[] color;public bool glass;}
 [Serializable] class Info {public Surface[] materials;public int bones,triangles;}
 [Serializable] class Catalog {public Info NeonMelee,NeonGunner,NeonAoe,NeonHeavy,NeonRifle;}
 static Catalog catalog;
 static void EnsureImports(){AssetDatabase.Refresh();foreach(var raw in Directory.GetFiles(Root+"Models","*.fbx")){var file=raw.Replace('\\','/');var i=(ModelImporter)AssetImporter.GetAtPath(file);if(i.importAnimation||i.importCameras||i.importLights||i.animationType!=ModelImporterAnimationType.Legacy||!i.isReadable||i.materialImportMode!=ModelImporterMaterialImportMode.ImportStandard){i.importAnimation=false;i.importCameras=false;i.importLights=false;i.animationType=ModelImporterAnimationType.Legacy;i.isReadable=true;i.materialImportMode=ModelImporterMaterialImportMode.ImportStandard;i.SaveAndReimport();}}foreach(var raw in Directory.GetFiles(Root+"Textures","*.png",SearchOption.AllDirectories)){var file=raw.Replace('\\','/');var i=(TextureImporter)AssetImporter.GetAtPath(file);bool srgb=file.Contains("Albedo")||file.Contains("Emission");var type=file.Contains("Normal")?TextureImporterType.NormalMap:TextureImporterType.Default;if(i.maxTextureSize!=2048||i.sRGBTexture!=srgb||i.textureType!=type){i.maxTextureSize=2048;i.sRGBTexture=srgb;i.textureType=type;i.SaveAndReimport();}}}
 public static void Build(){EnsureImports();catalog=JsonUtility.FromJson<Catalog>(File.ReadAllText(Root+"manifest.json"));Directory.CreateDirectory(Root+"Materials");Directory.CreateDirectory(Root+"Prefabs");AssetDatabase.Refresh();foreach(string id in new[]{"NeonMelee","NeonGunner","NeonAoe","NeonHeavy"}){if(!File.Exists(Root+"Models/"+id+".fbx"))throw new Exception("Missing Neon actor source "+id);BuildActor(id);}AssetDatabase.SaveAssets();}
 static Info Get(string id)=>id=="NeonMelee"?catalog.NeonMelee:id=="NeonGunner"?catalog.NeonGunner:id=="NeonAoe"?catalog.NeonAoe:id=="NeonHeavy"?catalog.NeonHeavy:catalog.NeonRifle;
 static GameObject Import(string id){var o=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(Root+"Models/"+id+".fbx"));foreach(var a in o.GetComponentsInChildren<Animator>())UnityEngine.Object.DestroyImmediate(a);foreach(var a in o.GetComponentsInChildren<Animation>())UnityEngine.Object.DestroyImmediate(a);foreach(var r in o.GetComponentsInChildren<Renderer>()){var names=r.sharedMaterials.Select(m=>m?m.name:"").ToArray();r.sharedMaterials=names.Select(name=>Material(id,Get(id).materials.FirstOrDefault(m=>name.StartsWith(m.name,StringComparison.Ordinal))??throw new Exception(id+" unmatched material ["+name+"] expected "+string.Join("|",Get(id).materials.Select(m=>m.name))))).ToArray();}return o;}
 static Material Material(string id,Surface s){string path=Root+"Materials/"+id+"_"+s.id+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find("Standard"));AssetDatabase.CreateAsset(m,path);}Texture2D Tex(string f)=>string.IsNullOrEmpty(f)?null:AssetDatabase.LoadAssetAtPath<Texture2D>(Root+"Textures/"+id+"/"+f);m.mainTexture=Tex(s.maps.Albedo);m.color=m.mainTexture?Color.white:s.color!=null&&s.color.Length>=3?new Color(s.color[0],s.color[1],s.color[2],s.color.Length>3?s.color[3]:1):Color.white;if(Tex(s.maps.Normal)){m.SetTexture("_BumpMap",Tex(s.maps.Normal));m.EnableKeyword("_NORMALMAP");m.SetFloat("_BumpScale",.7f);}m.SetTexture("_MetallicGlossMap",Tex(s.maps.MetalSmooth));m.EnableKeyword("_METALLICGLOSSMAP");m.SetTexture("_OcclusionMap",Tex(s.maps.Occlusion));if(Tex(s.maps.Emission)){m.SetTexture("_EmissionMap",Tex(s.maps.Emission));m.SetColor("_EmissionColor",Color.white*.7f);m.EnableKeyword("_EMISSION");}if(s.glass){m.SetFloat("_Mode",1);m.SetFloat("_Cutoff",.3f);m.EnableKeyword("_ALPHATEST_ON");m.renderQueue=2450;}m.enableInstancing=true;EditorUtility.SetDirty(m);return m;}
 static void BuildActor(string id){var root=new GameObject(id);var model=Import(id);model.name="Source";model.transform.SetParent(root.transform,false);float height=id=="NeonHeavy"?2.2f:id=="NeonAoe"?1:id=="NeonMelee"?2.05f:1.95f;var b=Art.RenderedBounds(model);if(b.size.y<.001f)throw new Exception("Empty actor "+id);model.transform.localScale*=height/b.size.y;b=Art.RenderedBounds(model);model.transform.position-=new Vector3(b.center.x,b.min.y,b.center.z);
  if(id=="NeonHeavy"){var motionRoot=new GameObject("motionRoot").transform;motionRoot.SetParent(model.transform,false);motionRoot.position=new Vector3(0,1.1f,0);var bones=model.GetComponentsInChildren<SkinnedMeshRenderer>().SelectMany(s=>s.bones).Distinct().ToArray();foreach(var bone in bones.Where(t=>!bones.Contains(t.parent)))bone.SetParent(motionRoot,true);}  Transform Bone(string name)=>model.GetComponentsInChildren<Transform>().First(t=>t.name==name);
  if(id=="NeonGunner")foreach(string side in new[]{"L","R"}){float sign=side=="L"?1:-1;foreach(var pair in new[]{new[]{"upperarm.","forearm."},new[]{"forearm.","hand."}}){var bone=Bone(pair[0]+side);var child=Bone(pair[1]+side);var direction=pair[0]=="upperarm."?new Vector3(side=="L"?.08f:-.18f,-.5f,.15f):new Vector3(side=="L"?.35f:0,.02f,.45f);bone.rotation=Quaternion.FromToRotation(child.position-bone.position,direction)*bone.rotation;}}
  var anchor=id=="NeonAoe"?Bone("spine"):Bone("hand.R");Vector3 muzzle=anchor.position+Vector3.forward*(id=="NeonHeavy"?.55f:.6f);
  if(id=="NeonGunner"||id=="NeonAoe"){var gun=Import("NeonRifle");gun.name="Fitted credited service rifle";float factor=id=="NeonAoe"?.65f:1;gun.transform.localScale=Vector3.one*factor;gun.transform.SetParent(anchor,true);FitGun(gun,id=="NeonAoe"?new Vector3(0,.65f,.4f):anchor.position+Vector3.forward*.25f);var gb=MeshBounds(gun);muzzle=new Vector3(gb.center.x,gb.center.y,gb.max.z);}
  var shot=new GameObject("ShotOrigin").transform;shot.SetParent(anchor,false);shot.position=muzzle;NeonCombatClips.Bake(root,id);PrefabUtility.SaveAsPrefabAsset(root,Root+"Prefabs/"+id+".prefab");UnityEngine.Object.DestroyImmediate(root);
 }
 static Vector3[] Points(GameObject gun)=>gun.GetComponentsInChildren<MeshFilter>().SelectMany(m=>m.sharedMesh.vertices.Select(v=>m.transform.TransformPoint(v))).ToArray();
 static Bounds MeshBounds(GameObject gun){var pts=Points(gun);var b=new Bounds(pts[0],Vector3.zero);foreach(var p in pts)b.Encapsulate(p);return b;}
 static void FitGun(GameObject gun,Vector3 center){var pts=Points(gun);var b=MeshBounds(gun);int axis=b.size.x>b.size.y?(b.size.x>b.size.z?0:2):(b.size.y>b.size.z?1:2);float length=b.size[axis];float Radius(bool plus){var end=pts.Where(v=>plus?v[axis]>b.max[axis]-length*.15f:v[axis]<b.min[axis]+length*.15f).ToArray();var eb=new Bounds(end[0],Vector3.zero);foreach(var v in end)eb.Encapsulate(v);var size=eb.size;size[axis]=0;return size.magnitude;}var dir=Vector3.zero;dir[axis]=Radius(true)<Radius(false)?1:-1;gun.transform.rotation=Quaternion.FromToRotation(dir,Vector3.forward)*gun.transform.rotation;b=MeshBounds(gun);if(b.size.x>b.size.y)gun.transform.rotation=Quaternion.AngleAxis(90,Vector3.forward)*gun.transform.rotation;b=MeshBounds(gun);gun.transform.position+=center-b.center;}
 public static void Proof(){Build();var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);RenderSettings.ambientLight=new Color(.35f,.37f,.42f);var light=new GameObject("Proof key").AddComponent<Light>();light.type=LightType.Directional;light.intensity=1.1f;light.shadows=LightShadows.Soft;light.transform.rotation=Quaternion.Euler(50,-30,0);var camera=new GameObject("Proof gameplay camera").AddComponent<Camera>();camera.orthographic=true;camera.transform.rotation=Quaternion.Euler(50,45,0);camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.04f,.05f,.07f);var lines=new List<string>();
  foreach(string id in new[]{"NeonMelee","NeonGunner","NeonAoe","NeonHeavy"}){var prefab=Resources.Load<GameObject>("Detailed/NeonEnemies/Prefabs/"+id);if(!prefab)continue;var model=UnityEngine.Object.Instantiate(prefab);var idle=Resources.Load<AnimationClip>("NeonEnemyAnimations/"+id+"/Idle");idle.SampleAnimation(model,0);var b=Art.RenderedBounds(model);if(Mathf.Abs(b.min.y)>.15f)throw new Exception(id+" notgrounded: "+b);if(b.size.y>3)throw new Exception(id+" scaleinvalid");var skins=model.GetComponentsInChildren<SkinnedMeshRenderer>();Vector3[] Snapshot(){var all=new List<Vector3>();foreach(var s in skins){var m=new Mesh();s.BakeMesh(m);all.AddRange(m.vertices);UnityEngine.Object.DestroyImmediate(m);}return all.ToArray();}var run=Resources.Load<AnimationClip>("NeonEnemyAnimations/"+id+"/RunForward");run.SampleAnimation(model,0);var a=Snapshot();run.SampleAnimation(model,.2f);var c=Snapshot();float delta=a.Zip(c,(x,y)=>Vector3.Distance(x,y)).Max();if(delta<.003f)throw new Exception(id+" noactualweightedmotion");foreach(var state in ActorAnimationBuilder.Names){var clip=Resources.Load<AnimationClip>("NeonEnemyAnimations/"+id+"/"+state);if(!clip||!clip.legacy)throw new Exception(id+" missingLegacyclip "+state);}foreach(string state in new[]{"Idle","RunForward","Fire","Death"}){var clip=Resources.Load<AnimationClip>("NeonEnemyAnimations/"+id+"/"+state);clip.SampleAnimation(model,state=="Idle"?0:state=="Death"?clip.length:.2f);Capture(camera,new Vector3(0,id=="NeonAoe"?.55f:1.1f,0),id+"-"+state+".png");}lines.Add(id+" skins="+skins.Length+" bones="+skins.Sum(s=>s.bones.Length)+" triangles="+skins.Sum(s=>s.sharedMesh.triangles.Length/3)+" bounds="+b+" sampledMeshDelta="+delta+" clips=11 ShotOrigin="+(model.GetComponentsInChildren<Transform>().Count(t=>t.name=="ShotOrigin")));UnityEngine.Object.DestroyImmediate(model);}
  File.WriteAllLines(Out+"unity-proof.txt",lines);AssetDatabase.SaveAssets();Debug.Log("NEON_PRODUCTION_PROOF_PASS");
 }
 static void Capture(Camera c,Vector3 target,string file){c.orthographicSize=2.3f;c.transform.position=target-c.transform.forward*20;var rt=new RenderTexture(1200,1000,24);c.targetTexture=rt;c.Render();RenderTexture.active=rt;var im=new Texture2D(1200,1000,TextureFormat.RGB24,false);im.ReadPixels(new Rect(0,0,1200,1000),0,0);im.Apply();File.WriteAllBytes(Out+file,im.EncodeToPNG());c.targetTexture=null;RenderTexture.active=null;UnityEngine.Object.DestroyImmediate(im);UnityEngine.Object.DestroyImmediate(rt);}
}
